{
      "@context": "https://schema.org",
      "@type": "FAQPage",
      "mainEntity": [

          {
            "@type": "Question",
            "name": "What are Cisco Services?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Cisco Services focus on your entire IT lifecycle, helping you deploy, operate, and optimize your IT infrastructure. Whether you need technical support or expert planning for new projects through professional services, we provide the guidance needed to keep your network, security, and collaboration tools running at their best. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "What is the difference between Cisco Support and Cisco Professional Services?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Cisco Support focuses on software updates, hardware replacement, and rapid issue resolution to keep your operations running smoothly. Cisco Professional Services provide strategic consulting, design, and implementation expertise to help you build or transform your IT environment. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "What is Cisco IQ?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Cisco IQ is an AI-powered digital experience embedded in Cisco Support that connects your entire journey with Cisco Services. It provides insights, automation, and expert guidance to help you plan, manage, and optimize your IT environment. By adapting to your specific infrastructure, Cisco IQ helps you prevent outages, resolve issues faster, and stay on top of transformation. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "What are Resilient Infrastructure Services?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Resilient Infrastructure Services is our comprehensive path to shift organizations from a reactive, manual risk posture to a continuous, resilient operating model delivered at machine speed. Customers can access this offering through Cisco Support, Cisco Professional Services, or Partner-delivered services. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "How can Cisco Services help organizations adopt AI?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Cisco Services help you assess your current infrastructure to ensure it can support AI-driven workloads. Experts provide guidance on architecture, security, and data management to integrate AI technologies into your operations reliably. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "How do I get started with Cisco Services?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "You can get started by contacting your Cisco account manager or an authorized partner to discuss your specific business needs. They will help you identify the right service options for your current infrastructure and goals. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "Why choose Cisco Services?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Choosing IT services from Cisco gives you access to 40-plus years of deep technical expertise and a global partner network. Together we help minimize downtime, accelerate deployment, and ensure your IT investments deliver maximum value. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "How does the Cisco Services team work with my IT staff?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "Cisco Services and our network of partners act as an extension of your IT team. We provide the specialized expertise and tools needed to help your team manage complex environments more efficiently. "    
            }
          } , 

          {
            "@type": "Question",
            "name": "What business outcomes can Cisco Services help achieve?",
            "acceptedAnswer": {
              "@type": "Answer",
              "text": "IT services from Cisco help make your infrastructure more reliable, accelerate technology adoption, and reduce overall risk. These outcomes allow your organization to focus on innovation while maintaining a secure and high-performing IT environment. "    
            }
          }  

	 ]
}
